pub fn reset_camera(&mut self) {
    match self.dimension {
        SceneViewDimension::ThreeD => self.camera.reset(),
        SceneViewDimension::TwoD => self.camera_2d.reset(),
    }
}

fn handle_editor_camera_input(&mut self, response: &egui::Response) {
    match self.dimension {
        SceneViewDimension::ThreeD => self.camera.handle_input(response),
        SceneViewDimension::TwoD => self.camera_2d.handle_input(response),
    }
}

fn editor_camera_transform(&self) -> Transform {
    match self.dimension {
        SceneViewDimension::ThreeD => self.camera.to_transform(),
        SceneViewDimension::TwoD => self.camera_2d.to_transform(),
    }
}

fn editor_camera_eye(&self) -> Vec3 {
    match self.dimension {
        SceneViewDimension::ThreeD => self.camera.eye(),
        SceneViewDimension::TwoD => self.camera_2d.eye(),
    }
}

fn editor_view_projection(&self, viewport: [u32; 2]) -> Mat4 {
    match self.dimension {
        SceneViewDimension::ThreeD => {
            let aspect = viewport[0].max(1) as f32 / viewport[1].max(1) as f32;
            self.camera.view_projection(aspect)
        }
        SceneViewDimension::TwoD => self.camera_2d.view_projection(viewport),
    }
}
